/** @brief rt 为任务，expected_boot 为所需模式，out 为最终版本；进 Boot 首错即停，回 App 有界重询。 */
static bool wait_mode(fwd_ota_runtime* rt, bool expected_boot, ota_reply* out) {
    if (rt == nullptr || out == nullptr) return false;
    if (!expected_boot) return wait_app_ready(rt, out);
    for (unsigned attempt = 0U; attempt < 30U; ++attempt) {
        if (ota_stopping(rt)) return false;
        const useconds_t delay_us = (attempt == 0U) ? OTA_ENTER_BOOT_WAIT_US : OTA_MODE_POLL_INTERVAL_US;
