static constexpr useconds_t OTA_ENTER_APP_WAIT_US = 450000U;
/** @brief 有效响应仍为其它模式或Stage-4重询时的间隔，单位微秒；通信错误仍立即停止。 */
static constexpr useconds_t OTA_MODE_POLL_INTERVAL_US = 100000U;
/** @brief Stage-4回App版本探测最大尝试次数（首轮450ms + 最多8次500ms/100ms重询）。 */
static constexpr unsigned OTA_STAGE4_MAX_ATTEMPTS = 8U;

/** @brief 本次同步回调输出；借用事件载荷只在回调内复制。 */
struct completion { ota_reply* output; };
/** @brief context 为完成槽，event 为协议终态；复制有界响应与真实序号/耗时。 */
static void on_reply(void* context, const fwd_comm_event_t* event) {
    if (context == nullptr || event == nullptr) return;
    auto* result = static_cast<completion*>(context)->output;
    if (result == nullptr) return;
    result->sequence = event->sequence_id;
    result->elapsed = event->elapsed_ms;
    result->size = event->data_len;
    if (event->data_len > sizeof(result->data)) { result->size = 0U; return; }
    if (event->data_len > 0U) std::memcpy(result->data, event->data, event->data_len);
    if (event->status == FWD_COMM_REMOTE_NACK && event->data_len == 3U) result->nack_error = event->data[0];
}

aisoc_fwd_status_t ota_exchange(fwd_ota_runtime* rt, const ota_packet* packet, ota_reply* output) {
    if (rt == nullptr || packet == nullptr || output == nullptr) return AISOC_FWD_ERR_NULL_PTR;
    *output = {};
    if (rt->communication_error != AISOC_FWD_OK) return rt->communication_error;
    completion done = {output};
    const fwd_exchange_spec spec = {
        {packet->command, packet->response, static_cast<uint16_t>(packet->size), static_cast<uint16_t>(packet->size),
         packet->response_size, packet->response_size, true, 6U, 0U},
        {static_cast<uint8_t>(2U + rt->current), packet->command, packet->data, packet->size, packet->timeout_ms, 0U},
        on_reply, &done};
    auto status = fwd_exchange(rt->owner, &spec);
    // 正式 ACK 是信用字段+两字节保留，不使用旧 acked_cmd/seq 结构解释。
    if (status == AISOC_FWD_OK && packet->response == 0U) {
        if (output->data[0] > 32U || output->data[2] != 0U || output->data[3] != 0U)
            status = AISOC_FWD_ERR_INVALID_ARG;
    }
    // 锁存首个错误；上层即使再次调用也不发送，超时不按“温度不可读”继续升级。
    if (status != AISOC_FWD_OK) {
        rt->communication_error = status;
        rt->failed_node = static_cast<uint8_t>(2U + rt->current);
        rt->failed_command = packet->command;
    }
    rt->last_sequence = output->sequence;
    rt->last_elapsed_ms = output->elapsed;
    std::fprintf(stderr, "[OTA_PACKET] task_id=%llu target_node=%u cmd=0x%02X sequence_id=%u elapsed_ms=%u error_code=%d nack_error=%u\n",
        static_cast<unsigned long long>(rt->task_id), 2U + rt->current, packet->command, output->sequence,
        output->elapsed, status, output->nack_error);
    return status;
}

/** @brief rt 为任务，index 为节点0/1，reply 为16B版本响应；只查询一次。 */
static bool version(fwd_ota_runtime* rt, uint8_t index, ota_reply* reply) {
    if (rt == nullptr || reply == nullptr) return false;
    const uint8_t saved = rt->current;
    rt->current = index;
    const ota_packet packet = {1U, 2U, nullptr, 0U, 16U, 500U};
    const auto status = ota_exchange(rt, &packet, reply);
    rt->current = saved;
    return status == AISOC_FWD_OK && reply->data[0] == 2U;
}

/** @brief rt 为任务，output 为单次版本响应；非锁存探测 0x01->0x02 版本应答，超时不提前锁存错误。 */
static aisoc_fwd_status_t probe_version_once(fwd_ota_runtime* rt, ota_reply* output) {
    if (rt == nullptr || rt->owner == nullptr || output == nullptr) return AISOC_FWD_ERR_NULL_PTR;
    if (rt->communication_error != AISOC_FWD_OK) return rt->communication_error;
    *output = {};
    completion done = {output};
    const fwd_exchange_spec spec = {
        {1U, 2U, 0U, 0U, 16U, 16U, true, 6U, 0U},
        {static_cast<uint8_t>(2U + rt->current), 1U, nullptr, 0U, 500U, 0U},
        on_reply, &done};
    const auto status = fwd_exchange(rt->owner, &spec);
    rt->last_sequence = output->sequence;
    rt->last_elapsed_ms = output->elapsed;
    std::fprintf(stderr, "[OTA_PACKET] task_id=%llu target_node=%u cmd=0x01 sequence_id=%u elapsed_ms=%u error_code=%d nack_error=%u\n",
        static_cast<unsigned long long>(rt->task_id), 2U + rt->current, output->sequence,
        output->elapsed, status, output->nack_error);
    if (status == AISOC_FWD_OK && (output->size < 16U || output->data[0] != 2U)) {
        return AISOC_FWD_ERR_INVALID_ARG;
    }
    return status;
}

/** @brief rt 为任务，out 为回 App 后版本应答；在 0x22 提交后最多 8 次有界重询并锁存终态错误。 */
static bool wait_app_ready(fwd_ota_runtime* rt, ota_reply* out) {
    if (rt == nullptr || rt->owner == nullptr || out == nullptr) return false;
    aisoc_fwd_status_t last_err = AISOC_FWD_ERR_TIMEOUT;
    for (unsigned attempt = 0U; attempt < OTA_STAGE4_MAX_ATTEMPTS; ++attempt) {
        if (!rt->owner->running || ota_stopping(rt)) return false;
        const useconds_t delay_us = (attempt == 0U) ? OTA_ENTER_APP_WAIT_US : OTA_MODE_POLL_INTERVAL_US;
        usleep(delay_us);
        last_err = probe_version_once(rt, out);
        if (last_err == AISOC_FWD_OK) {
            const bool boot = (ota_read32(out->data + 12U) & 0x80000000U) != 0U;
            if (!boot) return true;
        } else if (last_err != AISOC_FWD_ERR_TIMEOUT) {
            // 非超时致命错误（如 REMOTE_NACK、SERIAL_IO、非法 0x02 负载）立即中止。
            break;
        }
    }
    // 非超时错误或 8 次重询全部耗尽仍未回 App，锁存通信故障上下文并中止升级。
    rt->communication_error = (last_err != AISOC_FWD_OK) ? last_err : AISOC_FWD_ERR_TIMEOUT;
    rt->failed_node = static_cast<uint8_t>(2U + rt->current);
    rt->failed_command = 1U;
    return false;
}

/** @brief rt 为任务，expected_boot 为所需模式，out 为最终版本；进 Boot 首错即停，回 App 有界重询。 */
static bool wait_mode(fwd_ota_runtime* rt, bool expected_boot, ota_reply* out) {
    if (rt == nullptr || out == nullptr) return false;
    if (!expected_boot) return wait_app_ready(rt, out);
    for (unsigned attempt = 0U; attempt < 30U; ++attempt) {
        if (ota_stopping(rt)) return false;
        const useconds_t delay_us = (attempt == 0U) ? OTA_ENTER_BOOT_WAIT_US : OTA_MODE_POLL_INTERVAL_US;
        usleep(delay_us);
        if (!version(rt, rt->current, out)) return false;
        const bool boot = (ota_read32(out->data + 12U) & 0x80000000U) != 0U;
        if (boot) return true;
    }
    return false;
}

/** @brief rt 为任务，index 为App节点；通信错误立即停止，传感器故障与明确加热活动分开处理。 */
static bool check_heater(fwd_ota_runtime* rt, uint8_t index) {
    if (rt == nullptr) return false;
    const uint8_t saved = rt->current;
    rt->current = index;
    ota_reply reply;
    const ota_packet packet = {0x14U, 0x15U, nullptr, 0U, 16U, 400U};
    const auto result = ota_exchange(rt, &packet, &reply);
    rt->current = saved;
    if (result != AISOC_FWD_OK) return false;
    const int16_t target = static_cast<int16_t>(reply.data[2] | (reply.data[3] << 8U));
    if (target > 0 || reply.data[7] != 0U) {
        rt->error = "HEATER_ACTIVE";
        return false;
    }

